// Test normalization logic from peruk25 dashboard
void main() {
  // Test cases for bar chart normalization
  final testCases = [
    ([10.0, 5.0], [1.0, 0.5]),      // Normal case
    ([10.0, 0.0], [1.0, 0.0]),      // No filtered items
    ([5.0, 5.0], [1.0, 1.0]),       // All filtered
    ([0.0, 0.0], [0.0, 0.0]),       // Empty
  ];

  for (final tc in testCases) {
    final values = tc[0] as List<double>;
    final expected = tc[1] as List<double>;

    // Replicate the generated code logic
    final maxVal = values.fold<double>(0.0, (a, b) => a > b ? a : b);
    final normalized = [for (final v in values) maxVal == 0 ? 0.0 : v / maxVal];

    final match = normalized.length == expected.length && 
      normalized.asMap().entries.every((e) => (e.value - expected[e.key]).abs() < 0.001);

    print('${values} => ${normalized} (expected ${expected}): ${match ? "✓" : "✗"}');
  }
}
EOF
